const MAX = 6000;                 // characters per chunk
const text = $input.first().json.text || '';
const file = $('Google Drive Trigger').first().json.name;
const runId = `${new Date().toISOString().slice(0,10)}-${$execution.id}`;

const out = [];
// split on page breaks first, then pack pages into chunks
const pages = text.split('\f');
let buf = '';
for (const page of pages) {
  if ((buf + page).length > MAX && buf) {
    out.push(buf); buf = page;
  } else {
    buf += '\f' + page;
  }
}
if (buf.trim()) out.push(buf);

return out.map((t, i) => ({
  json: { run_id: runId, source_file: file, chunk_index: i, text: t }
}));

const slug = s => String(s || '')
  .toUpperCase().replace(/[^A-Z0-9]+/g, '-').replace(/^-|-$/g, '');

const out = [];
const seen = new Set();

for (const item of $input.all()) {
  const p = item.json["output.products"] || item.json;
  const problems = [];

  // SKU: use theirs, else build a stable one
  let sku = slug(p.sku);
  if (!sku) sku = slug(`${p.brand || 'GEN'}-${p.model || p.name}`).slice(0, 40);
  if (!sku) problems.push('no sku');

  // duplicate within this same file
  if (seen.has(sku)) { problems.push('duplicate in file'); }
  seen.add(sku);

  const price = typeof p.supplier_price === 'number' ? p.supplier_price : null;
  if (price === null) problems.push('no price');
  if (price !== null && price <= 0) problems.push('price is zero or negative');

  const srp = typeof p.srp === 'number' ? p.srp : null;
  if (srp === null) problems.push('no SRP');
  if (srp !== null && srp <= 0) problems.push('SRP is zero or negative');

  if (!p.name) problems.push('no name');
  if ((p.confidence ?? 0) < 0.6) problems.push('low confidence');



  out.push({ json: {
    run_id: item.json['run_id'],
    source_file: item.json['source_file'],
    sku,
    name: String(p.name || '').trim().slice(0, 180),
    brand: /* p.brand ||  */'',
    model: p.model || '',
    supplier_price: price,
    srp: srp,
    markup_pct: 0,
    short_description: p.short_description || '',
    specs_json: JSON.stringify(p.specs || []),
    supplier_category: p.supplier_category || '',
    category: p.category || '',
    stock_qty: p.stock_qty ?? '',
    publish_at: '',
    approved: problems.length > 0 ? 'FALSE' : 'TRUE',
    confidence: p.confidence ?? 0,
    notes: problems.join('; '),
    needs_attention: problems.length > 0,
    status: 'pending',
  }});
}
return out;

// ===== Messy XLSX → LLM-ready tables =====
// Mode: Run Once for All Items
// Input: Extract from File (XLSX) — Header Row OFF, RAW Data ON

const CHUNK_ROWS = 40;        // data rows per LLM call
const MAX_CELL_LEN = 280;
const HEADER_SCAN_DEPTH = 6;
const FILL_DOWN = true;       // repeat values down merged/blank cells

const HEADER_WORDS = [
  'sku','code','item','part','model','brand','description','desc','product','name','article',
  'price','srp','dealer','reseller','net','cost','amount','list','supplier','wholesale',
  'qty','quantity','stock','on hand','available','moq','min','uom','unit','pack','size','pcs',
  'category','type','currency','php','usd','date','remarks','notes','spec','specification'
];

const colName = (i) => {
  let s = '', n = i;
  do { s = String.fromCharCode(65 + (n % 26)) + s; n = Math.floor(n / 26) - 1; } while (n >= 0);
  return s;
};

const clean = (v) => {
  if (v === null || v === undefined) return null;
  if (typeof v === 'number') return Number.isFinite(v) ? v : null;
  if (typeof v === 'boolean') return v;
  if (v instanceof Date) return v.toISOString().slice(0, 10);
  let s = String(v)
    .replace(/[\u200B-\u200D\uFEFF]/g, '')
    .replace(/\u00A0/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
  if (!s) return null;
  if (s.length > MAX_CELL_LEN) s = s.slice(0, MAX_CELL_LEN) + '…';
  return s;
};

// --- normalize any Extract-from-File shape into an array of cells ---
const toRow = (j) => {
  if (Array.isArray(j)) return { values: j, keys: null };
  if (j && Array.isArray(j.row)) return { values: j.row, keys: null };
  const keys = Object.keys(j || {});
  const idxKeys = keys.filter(k => /^row\[\d+\]$/.test(k));
  if (idxKeys.length) {
    const arr = [];
    for (const k of idxKeys) arr[Number(k.match(/\d+/)[0])] = j[k];
    return { values: Array.from(arr, v => (v === undefined ? null : v)), keys: null };
  }
  return { values: keys.map(k => j[k]), keys }; // header-row mode fallback
};

const isBlank = (r) => r.every(c => c === null);
const nonNull = (r) => r.filter(c => c !== null);

const headerScore = (r) => {
  const cells = nonNull(r);
  let hits = 0, nums = 0;
  for (const c of cells) {
    if (typeof c === 'number') { nums++; continue; }
    const s = String(c).toLowerCase();
    if (HEADER_WORDS.some(w => s.includes(w))) hits++;
  }
  const score = hits - nums * 0.5;
  return { score, ok: hits >= 2 && cells.length >= 2 && nums <= cells.length / 2 };
};

// ---------- 1. build the grid ----------
const input = $input.all();
let grid = [];
let namedHeaderPushed = false;

for (const it of input) {
  const { values, keys } = toRow(it.json ?? {});
  if (keys && !namedHeaderPushed) { grid.push(keys.map(clean)); namedHeaderPushed = true; }
  grid.push(values.map(clean));
}

const width = grid.reduce((m, r) => Math.max(m, r.length), 0);
grid = grid.map(r => { const c = r.slice(); while (c.length < width) c.push(null); return c; });

if (!grid.length || grid.every(isBlank)) {
  return [{ json: { error: 'EMPTY_SHEET', rows_in: input.length } }];
}

// ---------- 2. split into blocks ----------
const blocks = [];
let cur = [], blankRun = 0;
for (let i = 0; i < grid.length; i++) {
  const r = grid[i];
  if (isBlank(r)) { blankRun++; continue; }
  if (cur.length && (blankRun >= 2 || (blankRun >= 1 && headerScore(r).ok))) { blocks.push(cur); cur = []; }
  blankRun = 0;
  cur.push({ n: i + 1, cells: r });
}
if (cur.length) blocks.push(cur);

// ---------- 3. parse each block ----------
const out = [];

blocks.forEach((block, bi) => {
  // header
  let hIdx = -1, best = 0;
  for (let i = 0; i < Math.min(HEADER_SCAN_DEPTH, block.length); i++) {
    const s = headerScore(block[i].cells);
    if (s.ok && s.score > best) { best = s.score; hIdx = i; }
  }
  let headerCells = hIdx >= 0 ? block[hIdx].cells.slice() : null;
  // merge a stacked second header row
  if (hIdx >= 0 && block[hIdx + 1] && headerScore(block[hIdx + 1].cells).ok) {
    const nxt = block[hIdx + 1].cells;
    headerCells = headerCells.map((c, i) => [c, nxt[i]].filter(Boolean).join(' ') || null);
    hIdx++;
  }

  const context = [];
  const body = [];
  const start = hIdx >= 0 ? hIdx + 1 : 0;

  for (let i = 0; i < start; i++) if (nonNull(block[i].cells).length === 1) context.push(String(nonNull(block[i].cells)[0]));

  for (let i = start; i < block.length; i++) {
    const { n, cells } = block[i];
    const nn = nonNull(cells);
    if (!nn.length) continue;
    if (headerCells && headerScore(cells).ok && nn.length >= 2) continue; // repeated print header
    if (nn.length === 1) { body.push({ n, kind: 'section', text: String(nn[0]) }); continue; }
    const joined = nn.join(' ').toLowerCase();
    const kind = /^(grand\s*)?total\b|sub\s*total|^page \d|prepared by|terms & conditions/.test(joined) ? 'note' : 'data';
    body.push({ n, kind, cells });
  }

  // fill down merged / sparse columns
  if (FILL_DOWN) {
    const dataRows = body.filter(r => r.kind === 'data');
    for (let c = 0; c < width; c++) {
      const filled = dataRows.filter(r => r.cells[c] !== null).length;
      if (filled === 0 || filled > dataRows.length * 0.4) continue;
      let last = null;
      for (const r of dataRows) {
        if (r.cells[c] !== null) last = r.cells[c];
        else if (last !== null) r.cells[c] = last;
      }
    }
  }

  const columns = [];
  for (let c = 0; c < width; c++) {
    const label = headerCells ? headerCells[c] : null;
    const used = body.some(r => r.cells && r.cells[c] !== null);
    if (!label && !used) continue;
    columns.push({ col: colName(c), index: c, label: label ? String(label) : `col_${colName(c)}` });
  }

  const dataCount = body.filter(r => r.kind === 'data').length;
  if (!dataCount) return;

  // ---------- 4. chunk + render ----------
  let chunk = [], chunks = [];
  for (const r of body) {
    chunk.push(r);
    if (chunk.filter(x => x.kind === 'data').length >= CHUNK_ROWS) { chunks.push(chunk); chunk = []; }
  }
  if (chunk.length) chunks.push(chunk);

  chunks.forEach((rows, ci) => {
    const lines = [];
    lines.push(`### TABLE ${bi + 1} — part ${ci + 1}/${chunks.length} (spreadsheet rows ${rows[0].n}-${rows[rows.length - 1].n})`);
    if (context.length) lines.push(`CONTEXT: ${context.join(' | ')}`);
    lines.push(`HEADER_DETECTED: ${headerCells ? 'yes' : 'no — infer meaning from values'}`);
    lines.push('COLUMNS:');
    columns.forEach(c => lines.push(`  ${c.col} = ${c.label}`));
    lines.push(`DATA (pipe-separated in column order ${columns.map(c => c.col).join(',')}; "~" = empty):`);
    for (const r of rows) {
      if (r.kind === 'section') { lines.push(`R${r.n} [SECTION] ${r.text}`); continue; }
      const vals = columns.map(c => (r.cells[c.index] === null ? '~' : String(r.cells[c.index])));
      lines.push(`R${r.n}${r.kind === 'note' ? ' [NOTE]' : ''} | ${vals.join(' | ')}`);
    }

    out.push({
      json: {
        block: bi + 1,
        chunk: ci + 1,
        chunks_total: chunks.length,
        row_start: rows[0].n,
        row_end: rows[rows.length - 1].n,
        data_rows: rows.filter(r => r.kind === 'data').length,
        context,
        columns,
        table: lines.join('\n'),
      },
    });
  });
});

return out.length ? out : [{ json: { error: 'NO_DATA_ROWS_FOUND', blocks: blocks.length } }];
